const validSlug = s => /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(String(s || ''));
const posts = $input.all().map(item => item.json || {}).filter(post => post.status === 'published' && post.site === 'https://www.taskwise.ai' && validSlug(post.slug));
const requested = String($('Taskwise Blog Feed').first().json.query?.slug || '').trim();
if (requested) {
  const post = validSlug(requested) ? posts.find(item => item.slug === requested) : null;
  return [{json: {post: post ? {slug: post.slug, title: post.title || post.metatitle || '', shortsummary: post.shortsummary || '', subheading: post.subheading || '', content: post.content || '', coverimage: post.coverimage || '', inlineimage: post.inlineimage || '', category: post.categorylabel || post.category || '', authorname: post.authorname || 'Taskwise Team', authorbio: post.authorbio || '', authoravatar: post.authoravatar || '', createdAt: post.createdAt || post.date || ''} : null}}];
}
return [{json: {posts: posts.map(post => ({slug: post.slug, title: post.title || post.metatitle || '', shortsummary: post.shortsummary || '', subheading: post.subheading || '', coverimage: post.coverimage || '', category: post.categorylabel || post.category || '', authorname: post.authorname || 'Taskwise Team', createdAt: post.createdAt || post.date || ''}))}}];
